#[test]
fn test_page_ranges_preserve_every_surviving_row_with_tombstones() {
    let rows: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let mut r: i32 = 0;
    let mut p: i32 = 0;
    let mut first: i32 = 0;
    let mut end: i32 = 0;
    while r < 140 {
        p = 1 + (r / 7);
        if (r % 3) == 0 {
            p = -7;
        }
        if (r % 5) == 0 {
            p = 0;
        }
        crate::port::cells_push(rows, p);
        crate::port::cells_push(rows, r);
        crate::port::cells_push(rows, 0);
        r += 1;
    }
    p = 1;
    while p <= 22 {
        first = pb_first(rows, 3, p);
        end = pb_after(rows, 3, p);
        crate::testport::assert_that((first >= 0) && ((first <= end) && (end <= 140)), "valid range");
        r = 0;
        while r < 140 {
            if crate::port::cells_at(rows, r * 3) == p {
                crate::testport::assert_that((r >= first) && (r < end), "every old-scan hit is inside the range in the same order");
            }
            r += 1;
        }
        p += 1;
    }
}
#[test]
fn test_zero_based_trace_pages_and_absent_pages() {
    let rows: &mut crate::port::Cells = &mut crate::port::Cells::new();
    crate::port::cells_push(rows, 0);
    crate::port::cells_push(rows, 0);
    crate::port::cells_push(rows, 2);
    crate::port::cells_push(rows, 2);
    crate::testport::assert_eq(pb_first(rows, 1, 0), 0, "page zero starts at zero");
    crate::testport::assert_eq(pb_after(rows, 1, 0), 2, "page zero ends before positive pages");
    crate::testport::assert_eq(pb_first(rows, 1, 1), 2, "absent page has an empty range");
    crate::testport::assert_eq(pb_after(rows, 1, 1), 2, "absent page has an empty range");
    crate::testport::assert_eq(pb_after(rows, 1, 2), 4, "last page includes its last row");
}
#[test]
fn test_appended_column_pieces_have_a_separate_page_ordered_run() {
    let rows: &mut crate::port::Cells = &mut crate::port::Cells::new();
    crate::port::cells_push(rows, 1);
    crate::port::cells_push(rows, 1);
    crate::port::cells_push(rows, 2);
    crate::port::cells_push(rows, 2);
    crate::port::cells_push(rows, 3);
    crate::port::cells_push(rows, 3);
    crate::port::cells_push(rows, 1);
    crate::port::cells_push(rows, 1);
    crate::port::cells_push(rows, 2);
    crate::port::cells_push(rows, 3);
    crate::testport::assert_eq(pb_first_span(rows, 1, 3, 0, 6), 4, "original page three begins before the appended pieces");
    crate::testport::assert_eq(pb_first_span(rows, 1, 4, 0, 6), 6, "original page three ends at the immutable boundary");
    crate::testport::assert_eq(pb_first_span(rows, 1, 3, 6, 10), 9, "appended page three follows earlier pages' pieces");
    crate::testport::assert_eq(pb_first_span(rows, 1, 4, 6, 10), 10, "all appended pieces are retained");
}
#[test]
fn test_range_index_keeps_unordered_fixtures_and_deleted_rows() {
    let rows: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ix: &mut crate::port::Cells = &mut crate::port::Cells::new();
    crate::port::cells_push(rows, 2);
    crate::port::cells_push(rows, -7);
    crate::port::cells_push(rows, 1);
    crate::port::cells_push(rows, 2);
    crate::port::cells_push(rows, 0);
    crate::port::cells_push(rows, 3);
    pb_build_ranges(rows, 1, 0, 6, 4, ix);
    crate::testport::assert_eq(crate::port::cells_at(ix, 2), 2, "page one's first row");
    crate::testport::assert_eq(crate::port::cells_at(ix, 3), 3, "page one's end");
    crate::testport::assert_eq(crate::port::cells_at(ix, 4), 0, "page two includes its earlier row");
    crate::testport::assert_eq(crate::port::cells_at(ix, 5), 4, "page two includes its later row");
    crate::testport::assert_eq(crate::port::cells_at(ix, 8), 6, "empty page begins at the end");
    crate::testport::assert_eq(crate::port::cells_at(ix, 9), 6, "empty page stays empty");
}
